M = "⟨⟩"
_cache = {}


def val(spec):
    f, keys = spec.split(":", 1)
    d = _cache.setdefault(f, json.loads((SR / f).read_text()))
    for k in keys.split("|"):
        d = d[int(k)] if isinstance(d, list) else d[k]
    return d


