def main():
    text = "\n".join(p.read_text() for p in FILES)
    bad = []
    for ctx, spec, fmt in ENTRIES:
        try:
            filled = ctx.replace(M, fmt(val(spec)))
        except Exception as e:
            bad.append(f"cannot read {spec}: {e}"); continue
        n = text.count(filled)
        if n != 1:
            bad.append(f"found {n}x: {filled!r}  <- {spec}")
    for b in bad:
        print("  " + b)
    print(f"{len(ENTRIES) - len(bad)} of {len(ENTRIES)} Chapter 6 figures match their result files")
    mtext, mbad = MAIN.read_text(), []
    for ctx, spec, fmt in MAIN_ENTRIES:
        filled = ctx.replace(M, fmt(val(spec)))
        if mtext.count(filled) != 1:
            mbad.append(f"found {mtext.count(filled)}x: {filled!r}  <- {spec}")
    for b in mbad:
        print("  main file: " + b)
    print(f"{len(MAIN_ENTRIES) - len(mbad)} of {len(MAIN_ENTRIES)} scene-class figures in the main file match")
    return 1 if bad or mbad else 0


if __name__ == "__main__":
    sys.exit(main())
